<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {usePhase1,clone,p1ConfigError} from '@/pinia/phase1';
import {phaseSkills,stateNames} from './catalog';
import type {P1SkillId,P1State} from '@/views/AgentWork/interface';
const props=defineProps<{projectId?:string;embedded?:boolean;selectedSkills?:P1SkillId[]}>();const emit=defineEmits<{saved:[ids:P1SkillId[]]}>();
const store=usePhase1();const draft=ref(store.config(props.projectId||''));const feedback=ref('');const baseline=ref(draft.value.version);
watch(()=>props.projectId,()=>{draft.value=store.config(props.projectId||'');baseline.value=draft.value.version;feedback.value='';},{immediate:true});
const visibleSkills=computed(()=>props.selectedSkills||draft.value.selectedSkills);
function weatherChanged(){if(draft.value.weather.enabled&&!draft.value.selectedSkills.includes('p1-weather'))draft.value.selectedSkills.push('p1-weather');}
function validate(){const error=p1ConfigError({...draft.value,selectedSkills:visibleSkills.value});feedback.value=error;return !error;}
function commit(projectId=props.projectId){if(!projectId||!validate())return false;const ok=store.saveConfig(projectId,{...clone(draft.value),selectedSkills:[...visibleSkills.value]},store.configs[projectId]?baseline.value:undefined);feedback.value=ok?'配置已保存；在监听运单受控更新，72小时截止不延长。':store.error;if(ok){baseline.value=store.config(projectId).version;draft.value.version=baseline.value;emit('saved',visibleSkills.value);}return ok;}
defineExpose({validate,commit});
</script>
<template><section class="p1-config"><h2>一期事件与规则配置</h2><p class="p1-muted">只支持一装一卸。间隔指同一异常的重复提醒间隔；基础事件由回调模拟产生，规则直接执行。</p>
<fieldset v-if="!embedded"><legend>业务 Skill · 选中后在做任务展示</legend><div class="p1-grid"><label v-for="skill in phaseSkills" :key="skill.id"><input type="checkbox" :value="skill.id" v-model="draft.selectedSkills"/>{{skill.name}}<small>{{skill.description}}</small></label></div></fieldset>
<fieldset><legend>监听事件配置</legend><div class="p1-grid"><section><label><input type="checkbox" v-model="draft.deviation.enabled"/>线路偏离事件</label><label>偏离半径（米）<input type="number" min="1" v-model.number="draft.deviation.radiusMeters" :disabled="!draft.deviation.enabled"/></label><label>重复提醒间隔（分钟）<input type="number" min="1" v-model.number="draft.deviation.repeatMinutes" :disabled="!draft.deviation.enabled"/></label></section><section v-for="type in (['offline','parking'] as const)" :key="type"><label><input type="checkbox" v-model="draft[type].enabled"/>{{type==='offline'?'在途离线事件':'超时停车事件'}}</label><label>{{type==='offline'?'离线':'停车'}}时长（分钟）<input type="number" min="1" v-model.number="draft[type].thresholdMinutes" :disabled="!draft[type].enabled"/></label><label>重复提醒间隔（分钟）<input type="number" min="1" v-model.number="draft[type].repeatMinutes" :disabled="!draft[type].enabled"/></label></section></div><h3>恶劣天气预警</h3><label><input type="checkbox" v-model="draft.weather.enabled" @change="weatherChanged"/>恶劣天气监听</label><p class="p1-muted">开启后增加恶劣天气预警任务；预计订阅成功后的次日0点生效，最长72小时，运单结束取消。不增加研判参数，不发送车机提醒。当前为Mock，数据专用服务尚待确认。</p><h3>围栏事件</h3><label class="p1-inline"><input type="checkbox" value="origin" v-model="draft.fenceTargets"/>起始地（进、出）</label><label class="p1-inline"><input type="checkbox" value="destination" v-model="draft.fenceTargets"/>目的地（进、出）</label></fieldset>
<fieldset><legend>固定规则配置 · 跳过大模型研判</legend><div class="p1-grid"><section><label><input type="checkbox" v-model="draft.lateDeparture.enabled"/>晚发异常</label><label>晚发时间（分钟）<input type="number" min="1" v-model.number="draft.lateDeparture.graceMinutes" :disabled="!draft.lateDeparture.enabled"/></label></section><section><label><input type="checkbox" v-model="draft.lateArrival.enabled"/>晚到异常</label><label>晚到时间（分钟）<input type="number" min="1" v-model.number="draft.lateArrival.graceMinutes" :disabled="!draft.lateArrival.enabled"/></label></section></div><h3>围栏更新运单状态</h3><label v-for="state in (['loading','in_transit','arrived','completed'] as Exclude<P1State,'pending'>[])" :key="state" class="p1-inline"><input type="checkbox" :value="state" v-model="draft.statusUpdates"/>{{stateNames[state]}}</label><p class="p1-muted">未勾选状态仍保留发车/到达事实。晚发、晚到看事实是否发生，不以当前状态不等于某个值判断。</p></fieldset>
<p v-if="!draft.fenceTargets.includes('origin')||!draft.fenceTargets.includes('destination')" role="status" class="p1-warning">缺少起始地/目的地围栏时，对应发车/到达判断可能没有依据；不会暗中打开监听或直接造异常。</p><p class="p1-muted">Mock 能力模式可演示可控偏离半径；白皮书能力模式会阻断未确认的半径能力，停车/离线仅支持10分钟的倍数。真实接口尚未接通。</p><button v-if="!embedded" @click="commit()">保存配置</button><p role="status">{{feedback}}</p></section></template>
<style src="./phase.css"></style>
